//#region Jaren JSLT dispatcher
// Compiles match paths, schema predicates, and query bodies once, then
// evaluates transformations through ranked per-mode dispatch tables.

import {
  compileJSONPath,
  JSONPathSyntaxError,
} from '../path.js';
import {
  RE_NAME_NEEDS_ESCAPE,
  appendName,
  compileSegmentP,
  descentCeilingOption,
  runSegmentsP,
  withDescentCeiling,
} from '../segments.js';
import {
  CARD_MANY,
  normalizeQuery,
  hostFailureText,
} from '../query/normalize.js';
import {
  compileNode,
  UNBOUND,
} from '../query/compile.js';
import {
  JsonQueryCompileError,
  JsonQueryRuntimeError,
} from '../query/errors.js';
import {
  EMPTY,
  Seq,
  appendItem,
  seqOf,
} from '../query/runtime.js';
import {
  JsltCompileError,
  JsltRuntimeError,
} from './errors.js';
import { setObjectMember } from '@jarenjs/core/object';

const hasOwn = Object.hasOwn;
const NO_RULE = Symbol('Jslt.NoRule');
const NO_EXTERNAL_VALUES = Object.freeze([]);

function composeDocPath(base, inner) {
  return inner.length === 0 ? base : base + inner;
}

// the one total host-failure projection of the package (see
// query/normalize.js): no raw .message read, no user coercion, no
// proxy-observable reflection

// One compiled query per distinct match-path source string: rules across
// modes matching the same path share the object, so a path the single
// walk cannot run is enumerated (`.paths(root)`) once per transform (see
// getQueryPaths), not once per mode. A shared query names the first rule
// that matches its path when the enumeration refuses (see matchPathsOf).
const matchRules = new WeakMap();

function compileMatchPath(rule, pathQueryCache, pathOptions, descentCeiling) {
  const match = rule.match;
  if (match === null || match.path === null)
    return null;
  const cached = pathQueryCache.get(match.path);
  if (cached !== undefined)
    return cached;
  try {
    const query = compileJSONPath(match.path, {
      pathFunctions: pathOptions === undefined ? undefined : pathOptions.pathFunctions,
      maxDescentDepth: descentCeiling,
    });
    pathQueryCache.set(match.path, query);
    matchRules.set(query, rule);
    return query;
  }
  catch (error) {
    if (!(error instanceof JSONPathSyntaxError))
      throw error;
    throw new JsltCompileError('JT0003',
      `invalid match path: ${error.message}`, match.pathDocPath, error);
  }
}

function compileMatchSchema(rule, compileTypeTest) {
  const match = rule.match;
  if (match === null || !match.schemaPresent)
    return null;
  if (compileTypeTest === null) {
    throw new JsltCompileError('JT0006',
      'schema matches require a type-test compiler (options.compileTypeTest)',
      match.schemaDocPath);
  }
  let test;
  try {
    test = compileTypeTest(match.schema, match.schemaDocPath);
  }
  catch (error) {
    throw new JsltCompileError('JT0005',
      `invalid match schema: ${hostFailureText(error)}`, match.schemaDocPath, error);
  }
  if (typeof test !== 'function') {
    const cause = new TypeError('the type-test compiler did not return a predicate function');
    throw new JsltCompileError('JT0005', cause.message, match.schemaDocPath, cause);
  }
  return test;
}

function appendDispatched(acc, selected, targetMode, depth, tctx, dispatch) {
  if (selected === EMPTY)
    return;
  if (selected instanceof Seq) {
    const items = selected.items;
    for (let i = 0; i < items.length; i++)
      appendItem(acc, dispatch(items[i], null, targetMode, depth, tctx));
    return;
  }
  appendItem(acc, dispatch(selected, null, targetMode, depth, tctx));
}

function createApplyEntry(ruleBox, tableBox, targetModes) {
  return {
    normalize(arg, docPath, opPath, scope, ctx, helpers) {
      let selector;
      let targetMode = ruleBox.mode;
      if (!Array.isArray(arg)) {
        selector = helpers.normalizeExpr(arg, opPath, scope, ctx);
      }
      else {
        if (arg.length < 1 || arg.length > 2)
          helpers.raise('JQ0003', 'query/apply-arguments', {}, opPath);
        selector = helpers.normalizeExpr(arg[0], opPath + '/0', scope, ctx);
        if (arg.length === 2) {
          if (typeof arg[1] !== 'string')
            helpers.raise('JQ0003', 'query/apply-mode', {}, opPath + '/1');
          targetMode = arg[1];
        }
      }
      targetModes.add(targetMode);
      ruleBox.targets.add(targetMode);
      const args = [selector];
      if (Array.isArray(arg) && arg.length === 2) // the explicit-mode form
        args.push(helpers.makeRaw(targetMode, opPath + '/1'));
      return { args, card: CARD_MANY };
    },
    compile(gets, args) {
      const selector = args[0];
      const get = gets[0];
      const targetMode = args.length === 2 ? args[1].value : ruleBox.mode;
      // slots are final once normalizeQuery returns; snapshot them here
      const locSlot = ruleBox.locSlot;
      const depthSlot = ruleBox.depthSlot;
      const tctxSlot = ruleBox.tctxSlot;
      // A bare root is a variable in the query AST: its zero-segment
      // path still has exactly the same location as a longer selector.
      const pathLike = selector.kind === 'path' || selector.kind === 'var';
      const rootSlot = selector.kind === 'var' ? selector.slot : selector.rootSlot;
      const currentPath = pathLike
        && rootSlot === 0
        && selector.external === false;
      const rootPath = pathLike
        && selector.name === 'root'
        && selector.external === true;
      const locatedPath = currentPath || rootPath;
      const segs = locatedPath
        ? (selector.segments ?? []).map(compileSegmentP)
        : null;

      return (frame) => {
        const tctx = frame[tctxSlot];
        const depth = frame[depthSlot] + 1;
        const dispatch = tableBox.dispatch;
        const acc = [];

        if (tableBox.needsLoc && locatedPath) {
          const baseLoc = currentPath ? frame[locSlot] : '$';
          if (baseLoc !== null) {
            const baseValue = frame[rootSlot];
            const result = runSegmentsP(segs, baseValue, baseLoc, frame[0]);
            const vals = result.vals;
            const paths = result.paths;
            for (let i = 0; i < vals.length; i++)
              appendItem(acc, dispatch(vals[i], paths[i], targetMode, depth, tctx));
            return seqOf(acc);
          }
        }

        appendDispatched(acc, get(frame), targetMode, depth, tctx, dispatch);
        return seqOf(acc);
      };
    },
  };
}

function wrapBodyCompileError(rule, error) {
  throw new JsltCompileError('JT0007',
    `rule body failed to compile: ${error.message}`,
    composeDocPath(rule.bodyDocPath, error.docPath), error);
}

function compileBody(rule, compileTypeTest, tableBox, targetModes, pathOptions) {
  const ruleBox = {
    mode: rule.mode,
    locSlot: -1,
    depthSlot: -1,
    tctxSlot: -1,
    targets: new Set(), // the modes this body's $apply calls dispatch into
  };
  const applyEntry = createApplyEntry(ruleBox, tableBox, targetModes);
  let normalized;
  let bodyGet;
  try {
    normalized = normalizeQuery(rule.body, {
      compileTypeTest,
      // the host's registered operators merge in, but $apply ALWAYS wins
      // (a pack cannot shadow the dispatch operator)
      extensions: pathOptions === undefined || pathOptions.extensions === undefined
        ? { '$apply': applyEntry }
        : { ...pathOptions.extensions, '$apply': applyEntry },
      functions: pathOptions === undefined ? undefined : pathOptions.functions,
      pathFunctions: pathOptions === undefined ? undefined : pathOptions.pathFunctions,
    });
    ruleBox.locSlot = normalized.frameSize;
    ruleBox.depthSlot = normalized.frameSize + 1;
    ruleBox.tctxSlot = normalized.frameSize + 2;
    bodyGet = compileNode(normalized.root);
  }
  catch (error) {
    if (error instanceof JsonQueryCompileError)
      wrapBodyCompileError(rule, error);
    throw error;
  }

  const userExternals = [];
  let rootSlot = -1;
  let pathSlot = -1;
  let readsPath = false;
  const externals = normalized.externals;
  for (let i = 0; i < externals.length; i++) {
    const external = externals[i];
    if (external.name === 'root') {
      rootSlot = external.slot;
    }
    else if (external.name === 'path') {
      pathSlot = external.slot;
      readsPath = true;
    }
    else {
      userExternals.push(external);
    }
  }

  return {
    bodyGet,
    frameSize: normalized.frameSize,
    locSlot: ruleBox.locSlot,
    depthSlot: ruleBox.depthSlot,
    tctxSlot: ruleBox.tctxSlot,
    rootSlot,
    pathSlot,
    readsPath,
    userExternals,
    targets: ruleBox.targets,
  };
}

//#region body memoization (the `memo` option)

// Ref-keyed body memoization: for an eligible rule, the same (location,
// value reference) pair MUST produce the same output, so the previous
// output can be returned by reference. Combined with copy-on-write state
// updates upstream and a reference-equality fast path downstream (the
// @jarenjs/view patcher), unchanged subtrees render in O(1) frame over
// frame. Eligibility is decided entirely at compile time:
//
//  - the body reads neither $root, $path nor user externals (those make
//    output depend on more than the matched value), and
//  - every mode reachable through the body's $apply calls is STABLE: all
//    of its rules are themselves body-clean, and their match paths do
//    not reference the root inside a filter (a second '$' in the path
//    source) - selection there depends only on (location, value), so
//    the child dispatches frozen inside a cached output stay correct.
//
// The cache is generational (two maps, swapped per transform call):
// entries unused for one full transform are dropped, bounding retention
// to the size of the live output.

function computeMemoEligibility(temporary) {
  const modeRules = new Map();
  for (let i = 0; i < temporary.length; i++) {
    const mode = temporary[i].rule.mode;
    const list = modeRules.get(mode);
    if (list === undefined)
      modeRules.set(mode, [i]);
    else
      list.push(i);
  }

  const bodyClean = new Array(temporary.length);
  const selectionStable = new Array(temporary.length);
  for (let i = 0; i < temporary.length; i++) {
    const body = temporary[i].body;
    bodyClean[i] = body.rootSlot < 0 && !body.readsPath && body.userExternals.length === 0;
    const match = temporary[i].rule.match;
    const path = match === null ? null : match.path;
    selectionStable[i] = path === null || path.indexOf('$', 1) === -1;
  }

  // modes with no rules fall to the built-in dispositions, which depend
  // only on (location, value): vacuously stable
  const modeOk = new Map();
  for (const name of modeRules.keys())
    modeOk.set(name, true);
  const ok = (name) => modeOk.get(name) !== false;

  let changed = true;
  while (changed) {
    changed = false;
    for (const [name, indexes] of modeRules) {
      if (modeOk.get(name) === false)
        continue;
      let good = true;
      for (let j = 0; j < indexes.length && good; j++) {
        const i = indexes[j];
        if (!bodyClean[i] || !selectionStable[i]) {
          good = false;
          break;
        }
        for (const target of temporary[i].body.targets) {
          if (!ok(target)) {
            good = false;
            break;
          }
        }
      }
      if (!good) {
        modeOk.set(name, false);
        changed = true;
      }
    }
  }

  const eligible = new Array(temporary.length);
  for (let i = 0; i < temporary.length; i++) {
    let good = bodyClean[i];
    if (good) {
      for (const target of temporary[i].body.targets) {
        if (!ok(target)) {
          good = false;
          break;
        }
      }
    }
    eligible[i] = good;
  }
  return eligible;
}

function memoizeBodyEvaluator(evaluate, memoCaches) {
  const box = { current: new Map(), previous: new Map() };
  memoCaches.push(box);
  return (value, loc, depth, tctx) => {
    if (loc === null)
      return evaluate(value, loc, depth, tctx);
    let entry = box.current.get(loc);
    if (entry === undefined) {
      entry = box.previous.get(loc);
      if (entry !== undefined)
        box.current.set(loc, entry);
    }
    if (entry !== undefined && entry.value === value)
      return entry.output;
    const output = evaluate(value, loc, depth, tctx);
    if (entry !== undefined) {
      entry.value = value;
      entry.output = output;
    }
    else {
      box.current.set(loc, { value, output });
    }
    return output;
  };
}

//#endregion

function makeBodyEvaluator(rule, body, userSlots) {
  const {
    bodyGet,
    frameSize,
    locSlot,
    depthSlot,
    tctxSlot,
    rootSlot,
    pathSlot,
  } = body;
  const ruleIndex = rule.index;
  const bodyDocPath = rule.bodyDocPath;
  const ruleDocPath = rule.docPath;
  const userCount = userSlots.length;
  const fullSize = frameSize + 3;

  return (value, loc, depth, tctx) => {
    const frame = new Array(fullSize);
    frame[0] = value;
    const externalValues = tctx.ruleExternalValues[ruleIndex];
    for (let i = 0; i < userCount; i++)
      frame[userSlots[i]] = externalValues[i];
    if (rootSlot >= 0)
      frame[rootSlot] = tctx.root;
    if (pathSlot >= 0)
      frame[pathSlot] = loc;
    frame[locSlot] = loc;
    frame[depthSlot] = depth;
    frame[tctxSlot] = tctx;

    try {
      return bodyGet(frame);
    }
    catch (error) {
      if (error instanceof JsltRuntimeError)
        throw error;
      if (!(error instanceof JsonQueryRuntimeError))
        throw error;
      const location = loc === null ? 'a location-less value' : `location ${loc}`;
      throw new JsltRuntimeError('JT2004',
        `rule ${ruleDocPath} failed at ${location}: ${error.message}`,
        composeDocPath(bodyDocPath, error.docPath), error);
    }
  };
}

function compileRules(model, compileTypeTest, tableBox, targetModes, memoEnabled, pathOptions, descentCeiling) {
  const rules = model.rules;
  const temporary = new Array(rules.length);
  const externalNames = [];
  const externalNameSet = new Set();
  let readsPath = false;

  const pathQueryCache = new Map();
  let pathRuleCount = 0;
  for (let i = 0; i < rules.length; i++) {
    const rule = rules[i];
    const pathQuery = compileMatchPath(rule, pathQueryCache, pathOptions, descentCeiling);
    if (pathQuery !== null)
      pathRuleCount++;
    const test = compileMatchSchema(rule, compileTypeTest);
    const body = compileBody(rule, compileTypeTest, tableBox, targetModes, pathOptions);
    readsPath = readsPath || body.readsPath;
    const userExternals = body.userExternals;
    for (let j = 0; j < userExternals.length; j++) {
      const name = userExternals[j].name;
      if (!externalNameSet.has(name)) {
        externalNameSet.add(name);
        externalNames.push(name);
      }
    }
    temporary[i] = { rule, pathQuery, test, body };
  }

  const externalIndexes = new Map();
  for (let i = 0; i < externalNames.length; i++)
    externalIndexes.set(externalNames[i], i);

  const memoEligible = memoEnabled ? computeMemoEligibility(temporary) : null;
  const memoCaches = [];

  const compiled = new Array(rules.length);
  for (let i = 0; i < temporary.length; i++) {
    const item = temporary[i];
    const userExternals = item.body.userExternals;
    const userSlots = new Array(userExternals.length);
    const userIndexes = new Array(userExternals.length);
    for (let j = 0; j < userExternals.length; j++) {
      userSlots[j] = userExternals[j].slot;
      userIndexes[j] = externalIndexes.get(userExternals[j].name);
    }
    const frozenSlots = Object.freeze(userSlots);
    const frozenIndexes = Object.freeze(userIndexes);
    let bodyEval = makeBodyEvaluator(item.rule, item.body, frozenSlots);
    if (memoEligible !== null && memoEligible[i])
      bodyEval = memoizeBodyEvaluator(bodyEval, memoCaches);
    compiled[i] = Object.freeze({
      index: item.rule.index,
      pathQuery: item.pathQuery,
      test: item.test,
      bodyEval,
      userSlots: frozenSlots,
      userIndexes: frozenIndexes,
    });
  }

  return {
    rules: Object.freeze(compiled),
    externals: Object.freeze(externalNames),
    readsPath,
    memoCaches,
    // rules sharing one match path (across modes, the TOC/render idiom)
    // enumerate it - when the single walk cannot run it - once per
    // transform call through tctx.queryPaths
    sharedQueries: pathRuleCount > pathQueryCache.size,
  };
}

//#region match pre-pass

// A mode's pre-pass is a trie over the input: one PrepassNode per
// location a match path selects (its rule bits, or a Set of ordinals past
// 32 path rules) or that lies on the spine of a deeper match, its
// `children` map keyed by the decoded member name or element index - the
// exact key forms the built-in rebuild walks with. A node answers "does a
// rule match here", "can a rule match below" and "through which
// children", and the rebuild hands each child its node, so a located
// dispatch below the root needs no lookup and a share rebuild copies
// every other child by reference without building its path string.
// Absent nodes are null; an empty pre-pass is a null root.
class PrepassNode {
  constructor(match, children) {
    this.match = match; // 0 (bit mode) / undefined (Set mode) when unmatched
    this.children = children; // Map, or null when nothing matches below
    // resolveLocation's cache of a one-child map's member name when it
    // needs no escape (null when there is none such), set on first use:
    // the trie is final once built
    this.sole = undefined;
  }
}

// Decode one normalized-path segment `['name']` (with RFC 9535 section
// 2.7 escapes) into the raw member name, or `[123]` into the integer
// index.
function parseSegmentKey(path, start, end) {
  if (path.charCodeAt(start + 1) === 0x27) { // single quote: a member name
    const from = start + 2;
    const to = end - 2;
    let i = from;
    while (i < to && path.charCodeAt(i) !== 0x5C) // backslash
      i++;
    if (i === to)
      return path.slice(from, to);
    let out = path.slice(from, i);
    while (i < to) {
      if (path.charCodeAt(i) !== 0x5C) {
        out += path[i];
        i++;
        continue;
      }
      const esc = path.charCodeAt(i + 1);
      if (esc === 0x75) { // 'u': the \u00XX control-character form
        out += String.fromCharCode(parseInt(path.slice(i + 2, i + 6), 16));
        i += 6;
        continue;
      }
      if (esc === 0x62) out += '\b';
      else if (esc === 0x74) out += '\t';
      else if (esc === 0x6E) out += '\n';
      else if (esc === 0x66) out += '\f';
      else if (esc === 0x72) out += '\r';
      else out += path[i + 1]; // a quote or backslash escapes itself
      i += 2;
    }
    return out;
  }
  let index = 0;
  for (let i = start + 1; i < end - 1; i++)
    index = index * 10 + (path.charCodeAt(i) - 0x30);
  return index;
}

// The end (exclusive) of the normalized-path segment opening at `start`
// (a '['): past the closing `']` of a quoted name, whose backslash
// escapes skip the escaped code unit, or past the ']' of an index.
function segmentEnd(path, start) {
  if (path.charCodeAt(start + 1) !== 0x27) // single quote
    return path.indexOf(']', start) + 1;
  let i = start + 2;
  for (;;) {
    const c = path.charCodeAt(i);
    if (c === 0x5C) // backslash
      i += 2;
    else if (c === 0x27)
      return i + 2;
    else
      i++;
  }
}

// The member name of a node's only child when its normalized form is the
// name itself, else null.
function soleName(node) {
  const children = node.children;
  if (children.size === 1) {
    const key = children.keys().next().value;
    if (typeof key === 'string' && !RE_NAME_NEEDS_ESCAPE.test(key))
      return key;
  }
  return null;
}

// The pre-pass node at a normalized path, or null when no rule of the
// mode matches there or below. A segment naming a spine's only member
// (the `$['store']['book']` of `$['store']['book'][7]`) is compared in
// place, without decoding it.
function resolveLocation(root, loc) {
  let node = root;
  for (let i = 1; i < loc.length;) {
    const children = node.children;
    if (children === null)
      return null;
    let sole = node.sole;
    if (sole === undefined) {
      sole = soleName(node);
      node.sole = sole;
    }
    if (sole !== null) {
      const from = i + 2;
      const close = from + sole.length;
      if (loc.charCodeAt(i + 1) === 0x27 && loc.charCodeAt(close) === 0x27
        && loc.charCodeAt(close + 1) === 0x5D && loc.startsWith(sole, from)) {
        node = children.get(sole);
        i = close + 2;
        continue;
      }
    }
    const end = segmentEnd(loc, i);
    node = children.get(parseSegmentKey(loc, i, end));
    if (node === undefined)
      return null;
    i = end;
  }
  return node;
}

function addMatch(node, ordinal, bitMode) {
  if (bitMode)
    node.match |= 1 << ordinal;
  else if (node.match === undefined)
    node.match = new Set([ordinal]);
  else
    node.match.add(ordinal);
}

// Insert one enumerated normalized path, creating its spine.
function insertPath(root, path, ordinal, bitMode) {
  let node = root;
  for (let i = 1; i < path.length;) {
    const end = segmentEnd(path, i);
    const key = parseSegmentKey(path, i, end);
    let children = node.children;
    if (children === null) {
      children = new Map();
      node.children = children;
    }
    let child = children.get(key);
    if (child === undefined) {
      child = new PrepassNode(bitMode ? 0 : undefined, null);
      children.set(key, child);
    }
    node = child;
    i = end;
  }
  addMatch(node, ordinal, bitMode);
}

// Every distinct match query enumerates the input once per transform
// call, however many modes (or ranked slots) reference it. Stylesheets
// without duplicate match paths bypass the cache (queryPaths === false).
function getQueryPaths(query, tctx) {
  let cache = tctx.queryPaths;
  if (cache === false)
    return matchPathsOf(query, tctx.root);
  if (cache === null) {
    cache = new Map();
    tctx.queryPaths = cache;
  }
  const cached = cache.get(query);
  if (cached !== undefined)
    return cached;
  const paths = matchPathsOf(query, tctx.root);
  cache.set(query, paths);
  return paths;
}

// A match path's enumeration raises what a rule body raises: a query
// runtime error (a descendant segment past its nesting bound) surfaces as
// JT2004 naming the rule and its match path, the error as the cause.
function matchPathsOf(query, root) {
  try {
    return query.paths(root);
  }
  catch (error) {
    if (!(error instanceof JsonQueryRuntimeError))
      throw error;
    const rule = matchRules.get(query);
    throw new JsltRuntimeError('JT2004',
      `rule ${rule.docPath} failed matching its path: ${error.message}`,
      composeDocPath(rule.match.pathDocPath, error.docPath), error);
  }
}

//#region single-walk matcher

// The match paths whose selectors are all names, indexes and wildcards
// (child or descendant segments) run together in ONE walk of the input
// instead of one enumeration each: an automaton state is one (path,
// segment) position, the walk carries the states alive at each value and
// descends only where one is, and builds the trie directly - no
// normalized path string is built and none is parsed back. Paths with a
// slice or a filter selector keep their enumeration (getQueryPaths) and
// are inserted after the walk, in ordinal order, so host functions run
// exactly as before. The walk calls no host code; it gives up - and the
// whole mode falls back to the per-path enumerations, which then raise
// exactly what they always raised - on any throw (an accessor, a host
// stack overflow) and before a descendant segment could reach a
// container as deep as the descent bound.

const WALK_ABORT = Symbol('Jslt.WalkAbort');

function walkableSegments(segments) {
  for (let i = 0; i < segments.length; i++) {
    const selectors = segments[i].selectors;
    for (let j = 0; j < selectors.length; j++) {
      const kind = selectors[j].kind;
      if (kind !== 'name' && kind !== 'index' && kind !== 'wildcard')
        return false;
    }
  }
  return true;
}

// One automaton step per (walkable path, segment position); the position
// past the last segment is the path's final state (`ordinal` >= 0).
function compileWalk(pathQueries, bitMasks, descentCeiling) {
  const steps = [];
  const starts = [];
  const enumerated = [];
  for (let ordinal = 0; ordinal < pathQueries.length; ordinal++) {
    const segments = pathQueries[ordinal].ast.segments;
    if (!walkableSegments(segments)) {
      enumerated.push(ordinal);
      continue;
    }
    starts.push(steps.length);
    for (let i = 0; i < segments.length; i++) {
      const selectors = segments[i].selectors;
      let names = null;
      let indexes = null;
      let wildcard = false;
      for (let j = 0; j < selectors.length; j++) {
        const selector = selectors[j];
        if (selector.kind === 'wildcard')
          wildcard = true;
        else if (selector.kind === 'name')
          (names ??= []).push(selector.name);
        else
          (indexes ??= []).push(selector.index);
      }
      steps.push({ ordinal: -1, descendant: segments[i].descendant, wildcard, names, indexes });
    }
    steps.push({ ordinal, descendant: false, wildcard: false, names: null, indexes: null });
  }
  if (starts.length === 0)
    return null;
  return {
    steps,
    starts,
    enumerated,
    bitMode: bitMasks,
    ceiling: descentCeiling,
  };
}

function addState(states, state) {
  if (states === null)
    return [state];
  if (!states.includes(state))
    states.push(state);
  return states;
}

// Whether an index selector list selects element `index` of an array of
// `length` elements (a negative index counts from the end).
function selectsIndex(indexes, index, length) {
  for (let j = 0; j < indexes.length; j++) {
    const selected = indexes[j];
    if ((selected < 0 ? length + selected : selected) === index)
      return true;
  }
  return false;
}

// The states a child inherits: every state alive for all children, plus
// the next state of each named/indexed step selecting this key (a member
// name, or an element index of an array of `length` elements).
function childStates(every, picks, steps, key, length) {
  let states = every;
  let copied = false;
  for (let p = 0; p < picks.length; p++) {
    const step = steps[picks[p]];
    if (length < 0
      ? step.names === null || !step.names.includes(key)
      : step.indexes === null || !selectsIndex(step.indexes, key, length))
      continue;
    if (!copied) {
      states = every === null ? [] : every.slice();
      copied = true;
    }
    states = addState(states, picks[p] + 1);
  }
  return states;
}

function walkNode(value, states, depth, walk) {
  const steps = walk.steps;
  const bitMode = walk.bitMode;
  let match = bitMode ? 0 : undefined;
  let matched = false;
  const container = typeof value === 'object' && value !== null;
  let every = null; // states alive at every child
  let picks = null; // steps selecting named or indexed children
  let descends = false;
  for (let s = 0; s < states.length; s++) {
    const state = states[s];
    const step = steps[state];
    if (step.ordinal >= 0) {
      if (bitMode)
        match |= 1 << step.ordinal;
      else
        (match ??= new Set()).add(step.ordinal);
      matched = true;
      continue;
    }
    if (!container)
      continue;
    if (step.descendant) {
      every = addState(every, state);
      descends = true;
    }
    if (step.wildcard)
      every = addState(every, state + 1);
    if (step.names !== null || step.indexes !== null)
      picks = addState(picks, state);
  }
  if (!container || (every === null && picks === null))
    return matched ? new PrepassNode(match, null) : null;
  if (descends && depth >= walk.ceiling)
    throw WALK_ABORT;

  let children = null;
  if (Array.isArray(value)) {
    const length = value.length;
    if (every !== null) {
      for (let i = 0; i < length; i++) {
        const next = picks === null ? every : childStates(every, picks, steps, i, length);
        const child = walkNode(value[i], next, depth + 1, walk);
        if (child !== null)
          (children ??= new Map()).set(i, child);
      }
    }
    else {
      for (let p = 0; p < picks.length; p++) {
        const indexes = steps[picks[p]].indexes;
        if (indexes === null)
          continue;
        for (let j = 0; j < indexes.length; j++) {
          const index = indexes[j] < 0 ? length + indexes[j] : indexes[j];
          if (index < 0 || index >= length || (children !== null && children.has(index)))
            continue;
          const child = walkNode(value[index], childStates(null, picks, steps, index, length), depth + 1, walk);
          if (child !== null)
            (children ??= new Map()).set(index, child);
        }
      }
    }
  }
  else if (every !== null) {
    for (const key in value) {
      if (!hasOwn(value, key))
        continue;
      const next = picks === null ? every : childStates(every, picks, steps, key, -1);
      const child = walkNode(value[key], next, depth + 1, walk);
      if (child !== null)
        (children ??= new Map()).set(key, child);
    }
  }
  else {
    for (let p = 0; p < picks.length; p++) {
      const names = steps[picks[p]].names;
      if (names === null)
        continue;
      for (let j = 0; j < names.length; j++) {
        const name = names[j];
        if (!hasOwn(value, name) || (children !== null && children.has(name)))
          continue;
        const child = walkNode(value[name], childStates(null, picks, steps, name, -1), depth + 1, walk);
        if (child !== null)
          (children ??= new Map()).set(name, child);
      }
    }
  }
  if (children === null && !matched)
    return null;
  return new PrepassNode(match, children);
}

//#endregion

function enumeratePrepass(mode, tctx, root, ordinals) {
  const queries = mode.pathQueries;
  const bitMode = mode.bitMasks;
  for (let k = 0; k < ordinals.length; k++) {
    const ordinal = ordinals[k];
    const paths = getQueryPaths(queries[ordinal], tctx);
    for (let i = 0; i < paths.length; i++)
      insertPath(root, paths[i], ordinal, bitMode);
  }
  return root;
}

function buildPrepass(mode, tctx) {
  const walk = mode.walk;
  const bitMode = mode.bitMasks;
  let root = WALK_ABORT;
  let ordinals = mode.allOrdinals;
  if (walk !== null) {
    try {
      root = walkNode(tctx.root, walk.starts, 0, walk);
      ordinals = walk.enumerated;
    }
    catch {
      root = WALK_ABORT;
    }
  }
  if (root === WALK_ABORT || root === null)
    root = new PrepassNode(bitMode ? 0 : undefined, null);
  enumeratePrepass(mode, tctx, root, ordinals);
  if (root.children === null && (bitMode ? root.match === 0 : root.match === undefined))
    root = null;
  tctx.prepasses[mode.id] = root;
  return root;
}

//#endregion

function scanBitRules(mode, value, loc, depth, tctx, mask) {
  const pathBits = mode.pathBits;
  const tests = mode.tests;
  const bodyEvals = mode.bodyEvals;
  for (let i = 0; i < bodyEvals.length; i++) {
    // a zero mask also covers location-less values: no bit can be set
    const bit = pathBits[i];
    if (bit !== 0 && (mask & bit) === 0)
      continue;
    const test = tests[i];
    if (test !== null && !test(value))
      continue;
    return bodyEvals[i](value, loc, depth, tctx);
  }
  return NO_RULE;
}

function scanSetRules(mode, value, loc, depth, tctx, matched) {
  const pathOrdinals = mode.pathOrdinals;
  const tests = mode.tests;
  const bodyEvals = mode.bodyEvals;
  for (let i = 0; i < bodyEvals.length; i++) {
    const ordinal = pathOrdinals[i];
    if (ordinal >= 0 && (matched === undefined || !matched.has(ordinal)))
      continue;
    const test = tests[i];
    if (test !== null && !test(value))
      continue;
    return bodyEvals[i](value, loc, depth, tctx);
  }
  return NO_RULE;
}

function describeLocation(loc) {
  return loc === null ? 'a location-less value' : loc;
}

// `children` is the dispatched location's pre-pass children map (null
// when nothing matches below it, or when the mode tracks no matches);
// each child is dispatched with its node, so its own lookup is free.
// With `prune` (a share mode of path rules only) the map lists the only
// keys through which a deeper rule can still match: every other child is
// copied by reference without a dispatch and without building its
// normalized path.
function rebuildObject(value, loc, mode, depth, tctx, dispatchMode, fresh, children, prune) {
  const out = {};
  let changed = fresh;
  for (const key in value) {
    if (!hasOwn(value, key))
      continue;
    const node = children === null ? null : children.get(key) ?? null;
    if (prune && node === null) {
      setObjectMember(out, key, value[key]);
      continue;
    }
    const childLoc = loc === null ? null : appendName(loc, key);
    const child = dispatchMode(value[key], childLoc, mode, depth + 1, tctx, node);
    if (child === EMPTY) {
      changed = true;
      continue;
    }
    if (child instanceof Seq) {
      throw new JsltRuntimeError('JT2002',
        `member '${key}' at ${describeLocation(childLoc)} produced ${child.items.length} items`,
        mode.unmatchedPath);
    }
    setObjectMember(out, key, child);
    if (child !== value[key])
      changed = true;
  }
  return changed ? out : value;
}

function rebuildArray(value, loc, mode, depth, tctx, dispatchMode, fresh, children, prune) {
  const out = [];
  let changed = fresh;
  for (let i = 0; i < value.length; i++) {
    const node = children === null ? null : children.get(i) ?? null;
    if (prune && node === null) {
      out.push(value[i]);
      continue;
    }
    const childLoc = loc === null ? null : loc + '[' + i + ']';
    const child = dispatchMode(value[i], childLoc, mode, depth + 1, tctx, node);
    if (child === EMPTY) {
      changed = true;
    }
    else if (child instanceof Seq) {
      appendItem(out, child);
      changed = true;
    }
    else {
      out.push(child);
      if (child !== value[i])
        changed = true;
    }
  }
  return changed ? out : value;
}

// The share pruning decision lives in dispatchMode (one pre-pass node
// yields the match and the prune set); by the time the built-in rule
// rebuilds, descending is already known to be required or harmless.
function builtIn(value, loc, mode, depth, tctx, dispatchMode, children, prune) {
  if (mode.unmatched === 'error') {
    throw new JsltRuntimeError('JT2003',
      `no rule in mode ${JSON.stringify(mode.name)} matched ${describeLocation(loc)}`,
      mode.unmatchedPath);
  }

  if (typeof value !== 'object' || value === null)
    return value;

  const fresh = mode.unmatched === 'fresh';
  return Array.isArray(value)
    ? rebuildArray(value, loc, mode, depth, tctx, dispatchMode, fresh, children, prune)
    : rebuildObject(value, loc, mode, depth, tctx, dispatchMode, fresh, children, prune);
}

function compileMode(modelMode, compiledRules, prepassIdOf, walkCeiling, fallbackUnmatched, fallbackPath) {
  const rankedRules = modelMode === null ? NO_EXTERNAL_VALUES : modelMode.rules;
  const name = modelMode === null ? '' : modelMode.name;
  const unmatched = modelMode === null ? fallbackUnmatched : modelMode.unmatched;
  const unmatchedPath = modelMode === null ? fallbackPath : modelMode.unmatchedPath;
  let pathCount = 0;
  let allPathRules = true;
  for (let i = 0; i < rankedRules.length; i++) {
    const compiled = compiledRules[rankedRules[i].index];
    if (compiled.pathQuery === null)
      allPathRules = false;
    else
      pathCount++;
  }

  const bitMasks = pathCount <= 32;
  const pathBits = bitMasks ? new Array(rankedRules.length) : null;
  const pathOrdinals = bitMasks ? null : new Array(rankedRules.length);
  const pathQueries = new Array(pathCount);
  const tests = new Array(rankedRules.length);
  const bodyEvals = new Array(rankedRules.length);
  const ruleIndexes = new Array(rankedRules.length);
  let ordinal = 0;
  for (let i = 0; i < rankedRules.length; i++) {
    const compiled = compiledRules[rankedRules[i].index];
    if (compiled.pathQuery === null) {
      if (bitMasks)
        pathBits[i] = 0;
      else
        pathOrdinals[i] = -1;
    }
    else {
      pathQueries[ordinal] = compiled.pathQuery;
      if (bitMasks)
        pathBits[i] = 1 << ordinal;
      else
        pathOrdinals[i] = ordinal;
      ordinal++;
    }
    tests[i] = compiled.test;
    bodyEvals[i] = compiled.bodyEval;
    ruleIndexes[i] = compiled.index;
  }

  return Object.freeze({
    // the pre-pass slot: modes with element-wise identical match-query
    // lists (the TOC/render idiom) share one pre-pass per transform
    id: prepassIdOf(pathQueries),
    name,
    unmatched,
    unmatchedPath,
    // Every rule of a share-mode chain requires a positional match: a
    // value without a match entry (off-spine, or location-less) can fire
    // nothing here or below and returns by reference without a scan.
    // Covers the zero-rule share mode (vacuously all-path).
    shareAllPaths: unmatched === 'share' && allPathRules,
    bitMasks,
    pathQueries: Object.freeze(pathQueries),
    // the single-walk automaton over the mode's walkable match paths
    // (null when none is), and every path ordinal for the fallback
    walk: walkCeiling === null ? null : compileWalk(pathQueries, bitMasks, walkCeiling),
    allOrdinals: Object.freeze(pathQueries.map((_, ordinal) => ordinal)),
    pathBits: pathBits === null ? null : Object.freeze(pathBits),
    pathOrdinals: pathOrdinals === null ? null : Object.freeze(pathOrdinals),
    tests: Object.freeze(tests),
    bodyEvals: Object.freeze(bodyEvals),
    ruleIndexes: Object.freeze(ruleIndexes),
  });
}

function buildModes(model, compiledRules, targetModes, walkCeiling) {
  const modelModes = new Map();
  const names = [];
  for (let i = 0; i < model.modes.length; i++) {
    const mode = model.modes[i];
    modelModes.set(mode.name, mode);
    names.push(mode.name);
  }
  for (const name of targetModes) {
    if (!modelModes.has(name)) {
      modelModes.set(name, null);
      names.push(name);
    }
  }

  const queryLists = [];
  const prepassIdOf = (pathQueries) => {
    for (let id = 0; id < queryLists.length; id++) {
      const seen = queryLists[id];
      if (seen.length !== pathQueries.length)
        continue;
      let same = true;
      for (let j = 0; j < seen.length && same; j++)
        same = seen[j] === pathQueries[j];
      if (same)
        return id;
    }
    queryLists.push(pathQueries);
    return queryLists.length - 1;
  };

  const modes = new Map();
  for (let i = 0; i < names.length; i++) {
    const name = names[i];
    const modelMode = modelModes.get(name);
    const runtime = modelMode === null
      ? Object.freeze({
          ...compileMode(null, compiledRules, prepassIdOf, walkCeiling, model.unmatched, model.unmatchedPath),
          name,
        })
      : compileMode(modelMode, compiledRules, prepassIdOf, walkCeiling, model.unmatched, model.unmatchedPath);
    modes.set(name, runtime);
  }
  return { modes, count: queryLists.length };
}

function resolveExternalValues(externalNames, compiledRules, ext) {
  const globalValues = new Array(externalNames.length);
  for (let i = 0; i < externalNames.length; i++) {
    const name = externalNames[i];
    globalValues[i] = ext != null && hasOwn(ext, name) ? ext[name] : UNBOUND;
  }

  const ruleValues = new Array(compiledRules.length);
  for (let i = 0; i < compiledRules.length; i++) {
    const indexes = compiledRules[i].userIndexes;
    if (indexes.length === 0) {
      ruleValues[i] = NO_EXTERNAL_VALUES;
      continue;
    }
    const values = new Array(indexes.length);
    for (let j = 0; j < indexes.length; j++)
      values[j] = globalValues[indexes[j]];
    ruleValues[i] = values;
  }
  return ruleValues;
}

/**
 * Compile a normalized stylesheet model into the reusable transformation
 * evaluator and its user-external metadata.
 * @param {object} model - result of normalizeJsltStylesheet
 * @param {object} [options] - compile options
 * @param {boolean} [walkPaths=true] - match the walkable paths of a mode
 *   in one walk; false enumerates every match path on its own (the
 *   reference the single walk must equal, for differential tests)
 * @returns {{evaluate: Function, externals: readonly string[]}}
 */
export function compileJsltDispatch(model, options = {}, walkPaths = true) {
  const compileTypeTest = typeof options.compileTypeTest === 'function'
    ? options.compileTypeTest
    : null;
  const maxDepth = options.maxDepth === undefined ? 1024 : options.maxDepth;
  if (!Number.isInteger(maxDepth) || maxDepth < 0)
    throw new TypeError('options.maxDepth must be a non-negative integer');
  // the descent bound of every descendant segment the stylesheet holds:
  // its match paths, and the paths inside its rule bodies
  const descentCeiling = descentCeilingOption(options.maxDescentDepth, 'options.maxDescentDepth');
  const memoEnabled = options.memo === true;
  // JSONPath function extensions reach both places a stylesheet embeds
  // a path: the rules' match paths, and the path strings inside rule
  // bodies (through the query normalizer).
  // options carried into each rule body's normalizeQuery: the RFC 9535
  // path-function registry, plus the host's registered operators
  // (options.extensions) and $call functions (options.functions) — the
  // JSLT operator registry (registry.js) flows in exactly here. Built
  // whenever ANY of the three is present.
  const bodyOptions = (options.pathFunctions == null
    && options.extensions == null && options.functions == null)
    ? undefined
    : {
      pathFunctions: options.pathFunctions ?? undefined,
      extensions: options.extensions ?? undefined,
      functions: options.functions ?? undefined,
    };

  const tableBox = {
    dispatch: null,
    needsLoc: false,
  };
  const targetModes = new Set();
  const compiled = withDescentCeiling(descentCeiling, () =>
    compileRules(model, compileTypeTest, tableBox, targetModes, memoEnabled, bodyOptions, descentCeiling));
  tableBox.needsLoc = model.anyPathRule || compiled.readsPath;
  const built = buildModes(model, compiled.rules, targetModes, walkPaths ? descentCeiling : null);
  const modes = built.modes;
  const rootMode = modes.get('');

  // `node` is the location's pre-pass node when the caller already holds
  // it (a rebuild hands each child its own, null when absent), or
  // undefined when only the location string is known
  function dispatchMode(value, loc, mode, depth, tctx, node) {
    if (depth > maxDepth) {
      throw new JsltRuntimeError('JT2001',
        `dispatch depth ${depth} exceeded maxDepth ${maxDepth}`,
        mode.unmatchedPath);
    }
    if (depth > tctx.highestDepth)
      tctx.highestDepth = depth;

    // location-less values can never match a path rule; modes reached
    // only through location-less items never pay for a pre-pass
    let match; // rule bit mask (bit mode) or Set of ordinals, or undefined
    let children = null;
    if (loc !== null && mode.pathQueries.length !== 0) {
      if (node === undefined) {
        let root = tctx.prepasses[mode.id];
        if (root === undefined)
          root = buildPrepass(mode, tctx);
        node = root === null ? null : resolveLocation(root, loc);
      }
      if (node !== null) {
        match = node.match;
        children = node.children;
      }
    }
    if (mode.shareAllPaths) {
      // every rule needs a positional match: values without one (and all
      // location-less values) can fire nothing here or anywhere below
      if (children === null) {
        if (match === undefined)
          return value;
      }
      else if (match === undefined || match === 0) {
        // on the spine of a deeper match only: descend without a scan
        return builtIn(value, loc, mode, depth, tctx, dispatchMode, children, true);
      }
    }
    const matched = mode.bitMasks
      ? scanBitRules(mode, value, loc, depth, tctx, match === undefined ? 0 : match)
      : scanSetRules(mode, value, loc, depth, tctx, match);
    if (matched !== NO_RULE)
      return matched;
    return builtIn(value, loc, mode, depth, tctx, dispatchMode, children, mode.shareAllPaths);
  }

  function dispatch(value, loc, modeName, depth, tctx) {
    const mode = modes.get(modeName);
    /* c8 ignore next 2 -- every static $apply target is registered at compile time */
    if (mode === undefined)
      throw new Error(`JSLT internal error: mode ${JSON.stringify(modeName)} was not compiled`);
    return dispatchMode(value, loc, mode, depth, tctx, undefined);
  }

  tableBox.dispatch = dispatch;
  Object.freeze(tableBox);

  if (rootMode.bodyEvals.length === 0 && rootMode.unmatched === 'share') {
    return Object.freeze({
      evaluate: (data) => data,
      externals: compiled.externals,
    });
  }

  const modeCount = built.count;
  const externalNames = compiled.externals;
  const compiledRules = compiled.rules;
  const sharedQueries = compiled.sharedQueries;
  const memoCaches = compiled.memoCaches;
  const rootLoc = tableBox.needsLoc ? '$' : null;
  // the all-unbound resolution is a compile-time constant; calls without
  // user bindings (the common case) share it instead of re-resolving
  const unboundRuleValues = resolveExternalValues(externalNames, compiledRules, null);
  return Object.freeze({
    evaluate(data, ext) {
      // generation swap: entries unused for one full transform retire
      for (let i = 0; i < memoCaches.length; i++) {
        const box = memoCaches[i];
        const retired = box.previous;
        box.previous = box.current;
        retired.clear();
        box.current = retired;
      }
      const tctx = {
        root: data,
        ruleExternalValues: ext == null || externalNames.length === 0
          ? unboundRuleValues
          : resolveExternalValues(externalNames, compiledRules, ext),
        prepasses: new Array(modeCount),
        queryPaths: sharedQueries ? null : false,
        highestDepth: 0,
      };
      try {
        return dispatchMode(data, rootLoc, rootMode, 0, tctx, undefined);
      }
      catch (error) {
        // A synchronous JavaScript stack can be shallower than the
        // language's default 1024-dispatch guard. Never expose the host
        // RangeError for a recursive dispatch chain; preserve JT2001 as
        // the public resource-guard condition.
        if (error instanceof RangeError && tctx.highestDepth > 32) {
          throw new JsltRuntimeError('JT2001',
            `dispatch recursion exhausted the host call stack before maxDepth ${maxDepth}`,
            rootMode.unmatchedPath);
        }
        throw error;
      }
    },
    externals: externalNames,
  });
}

//#endregion
